import * as THREE from '../vendor/three.module.js';
import {BODIES} from './architecture.js';
import {toWorld} from './pose.js';
import {rebuildFaultWorld} from './fault-shutters.js';
export const GROWTH_ZONES=[{id:'dense-northwest',x:8,z:0,w:27,d:35},{id:'middle-east',x:40,z:0,w:45,d:50},{id:'open-south',x:0,z:50,w:134,d:42}];
const templates=new Map(),P=a=>new THREE.Vector3(...a);
function merge(list){const positions=[],normals=[];for(const source of list){const g=source.index?source.toNonIndexed():source;positions.push(...g.attributes.position.array);normals.push(...g.attributes.normal.array);if(g!==source)g.dispose();source.dispose();}return{position:new Float32Array(positions),normal:new Float32Array(normals)};}
function createTemplate(s,density){const buckets=new Map(),counts={coatedBodies:0,boneClusters:0,membranes:0,tubes:0},materials={vein:{color:0x79313f,roughness:.9},bone:{color:0xd9d1b7,roughness:.93},opaque:{color:0x735456,roughness:1,side:THREE.DoubleSide},thin:{color:0xc29496,roughness:.9,transparent:true,opacity:.32,depthWrite:false,side:THREE.DoubleSide}};
 const add=(geometry,mat,physical,age)=>{const key=[mat,physical,age].join(':');if(!buckets.has(key))buckets.set(key,{mat,physical,age,geometries:[]});buckets.get(key).geometries.push(geometry);};
 const tube=(points,r,mat='vein',physical=false,age='pre-existing-prototype')=>{counts.tubes++;const curve=new THREE.CatmullRomCurve3(points.map(P)),segments=points.length*3,geo=new THREE.TubeGeometry(curve,segments,r,6,false);if(physical){const vertices=[];for(const end of[0,1]){const center=curve.getPoint(end),off=end?segments*7:0;for(let j=0;j<6;j++){const a=new THREE.Vector3().fromBufferAttribute(geo.attributes.position,off+j),b=new THREE.Vector3().fromBufferAttribute(geo.attributes.position,off+j+1);const normal=curve.getTangent(end).multiplyScalar(end?1:-1),cross=a.clone().sub(center).cross(b.clone().sub(center));const pair=cross.dot(normal)>0?[a,b]:[b,a];vertices.push(...center.toArray(),...pair[0].toArray(),...pair[1].toArray());}}const caps=new THREE.BufferGeometry();caps.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));caps.computeVertexNormals();add(caps,mat,physical,age);}add(geo,mat,physical,age);};
 const sheet=(vertices,mat,physical=true,age='fault-response-prototype')=>{const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(vertices.flat(),3));g.setIndex([0,1,2,0,2,3]);g.computeVertexNormals();add(g,mat,physical,age);counts.membranes++;};
 const selected=BODIES.filter((b,i)=>density==='high'||density==='medium'?density==='high'||i%2===0:i%7===0);
 for(const b of selected){const pose=s.positions[b.id];counts.coatedBodies++;let seed=[...b.id].reduce((a,c)=>a*31+c.charCodeAt(0),17)>>>0;const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};const at=(x,y,z)=>{const p=toWorld(pose,{x,y,z});return[p.x,p.y,p.z];};
 for(let j=0;j<Math.max(2,Math.round((density==='high'?8:density==='medium'?5:3)*(pose.z>=50?.5:pose.x>=40?.75:1)));j++){const x=.7+random()*6,z=.7+random()*6;const r=.014+random()*.027;tube([at(x,6.035,.5),at(x+.4,6.05,3),at(x-.3,6.04,7.4)],r);if(j%2===0)tube([at(x,6.04,3),at(x+1,6.045,4),at(Math.min(7.5,x+1.6),6.035,5)],r*.6);tube([at(-.09,.4,z),at(-.08,3,z+.3),at(-.09,5.8,z-.2)],r);if(j<2)tube([at(.6,-.05,z),at(4,-.055,z+.3),at(7.3,-.05,z-.2)],r);}}
 const protectedIds=new Set(['R2','L1','V3','V1','SM0','SM1','BR3','SM3']);const candidates=BODIES.filter(b=>!protectedIds.has(b.id)&&s.positions[b.id].y+6<16),limit=density==='high'?20:density==='medium'?9:2;
 for(let i=0;i<Math.min(limit,candidates.length);i++){const b=candidates[(i*7)%candidates.length],p=s.positions[b.id],y=p.y+6,ceiling=Math.min(19.2,y+3.6+(i%3));const a=toWorld(p,{x:2.2,z:2.4});tube([[a.x,y,a.z],[a.x+.5,ceiling-1,a.z+1],[a.x+2,ceiling,a.z+2]],.25+(i%4)*.11,'bone',true);tube([[a.x+.5,ceiling-1,a.z+1],[a.x-1.5,ceiling-.5,a.z+3]],.17,'bone',true);counts.boneClusters++;if(i%3===0&&density!=='low')sheet([[a.x-1,y+2.2,a.z+2],[a.x+3,y+2.3,a.z+2],[a.x+2.5,ceiling+1,a.z+2.4],[a.x-1.5,ceiling,a.z+2.4]],i%2?'thin':'opaque');}
 if(density!=='low'){
 // Low canopy veils affect views of upper buildings, but leave full walking headroom.
 sheet([[25.5,8.4,13.5],[31,8.6,13.5],[31.4,11,14],[25.8,11.4,14]],'thin');
 // A straight approach is blocked; the east side on the same real L1 roof remains open.
 sheet([[16.85,6,16.3],[20.5,6,16.3],[20.4,8.9,16.4],[16.9,8.5,16.4]],'opaque');
 tube([[16.9,6,16.3],[17.1,8.5,16.4],[19,9.1,16.5]],.17,'bone',true,'fault-response-prototype');
 tube([[20.5,6,16.3],[20.4,8.9,16.4],[21,9.4,17]],.19,'vein',true,'fault-response-prototype');}
 if(density==='high'){
 // A real 1.5m tear between two separate opaque sheets, not an invisible portal.
 sheet([[16.85,6,18.8],[20.9,6,18.8],[20.8,9.2,18.9],[16.9,8.6,19]],'opaque');sheet([[22.4,6,18.8],[24.7,6,18.8],[24.7,8.7,19],[22.5,9,18.9]],'opaque');
 // Seals this local north exit; the representative east exit is intentionally preserved.
 sheet([[13.2,6.1,8.45],[15.6,6.1,8.45],[15.7,9.3,8.5],[13.1,9,8.5]],'opaque');}
 return{counts,rows:[...buckets.values()].map(b=>({...merge(b.geometries),mat:materials[b.mat],physical:b.physical,age:b.age}))};}
export function growthTemplate(s){const key=s.fault.density+':'+JSON.stringify(s.positions);if(!templates.has(key)){templates.set(key,createTemplate(s,s.fault.density));while(templates.size>3)templates.delete(templates.keys().next().value);}return templates.get(key);}
function dispose(root){const geos=new Set(),mats=new Set();root.traverse(o=>{if(o.geometry)geos.add(o.geometry);if(o.material)mats.add(o.material);});geos.forEach(g=>g.dispose());mats.forEach(m=>m.dispose());}
export function updateFaultGrowth(v){const active=!!v.sim.fault?.stage20,key=active?v.sim.fault.density:'off';if(!active&&v.growthGroup){v.scene.remove(v.growthGroup);dispose(v.growthGroup);v.growthGroup=null;v.growthKey='off';}if(active&&v.growthKey!==key){if(v.growthGroup){v.scene.remove(v.growthGroup);dispose(v.growthGroup);}const g=new THREE.Group(),t=growthTemplate(v.sim);g.name='stage20-growth';g.userData.diagnosticId='organ:growth';g.userData.metrics=t.counts;for(const row of t.rows){const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.BufferAttribute(row.position,3));geo.setAttribute('normal',new THREE.BufferAttribute(row.normal,3));const m=new THREE.Mesh(geo,new THREE.MeshStandardMaterial(row.mat));m.userData.nonPhysical=!row.physical;m.userData.structureAge=row.age;g.add(m);}v.scene.add(g);v.growthGroup=g;v.growthKey=key;}if(v.growthGroup)v.growthGroup.visible=active;}
export function setFaultDensity(s,density){if(!s.fault?.stage20||!['low','medium','high'].includes(density))return false;const old=s.fault.density,ok=rebuildFaultWorld(s,()=>s.fault.density=density,()=>s.fault.density=old);if(ok){s.fault.worldCache?.clear();s.message='生体密度：'+{low:'少',medium:'中',high:'多'}[density]+'（配置と現在位置を保持）';}return ok;}
